{
  "name": "@tailwindcss/root",
  "private": true,
  "version": "1.0.0",
  "prettier": {
    "semi": false,
    "singleQuote": true,
    "printWidth": 100,
    "plugins": [
      "prettier-plugin-organize-imports"
    ],
    "overrides": [
      {
        "files": [
          "tsconfig.json"
        ],
        "options": {
          "parser": "jsonc"
        }
      },
      {
        "files": [
          "integrations/**/*.ts"
        ],
        "options": {
          "plugins": [
            "prettier-plugin-embed",
            "prettier-plugin-organize-imports"
          ]
        }
      }
    ]
  },
  "scripts": {
    "format": "prettier --write .",
    "lint": "prettier --check . && turbo lint",
    "build": "turbo build --filter=!./playgrounds/*",
    "postbuild": "node ./scripts/pack-packages.mjs",
    "dev": "turbo dev --filter=!./playgrounds/*",
    "test": "cargo test && vitest run --hideSkippedTests",
    "test:integrations": "vitest --root=./integrations",
    "test:ui": "pnpm run --filter=tailwindcss test:ui && pnpm run --filter=@tailwindcss/browser test:ui",
    "tdd": "vitest --hideSkippedTests",
    "bench": "vitest bench",
    "version-packages": "node ./scripts/version-packages.mjs",
    "vite": "pnpm run --filter=vite-playground dev",
    "nextjs": "pnpm run --filter=nextjs-playground dev"
  },
  "license": "MIT",
  "devDependencies": {
    "@playwright/test": "^1.62.1",
    "@types/node": "catalog:",
    "postcss": "catalog:",
    "postcss-import": "^16.1.1",
    "prettier": "catalog:",
    "prettier-plugin-embed": "^0.5.1",
    "prettier-plugin-organize-imports": "^4.3.0",
    "tsup": "^8.5.1",
    "turbo": "^2.10.8",
    "typescript": "^5.9.3",
    "vitest": "^4.1.10"
  },
  "packageManager": "pnpm@11.9.0"
}

# SPDX-FileCopyrightText: Copyright (c) 2025-2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
# SPDX-License-Identifier: Apache-2.0

[workspace]
members = [
    "lib/llm",
    "lib/rl",
    "lib/runtime",
    "lib/tokens",
    "lib/truthy",
    "lib/data-gen",
    "lib/kv-hashing",
    "lib/mocker",
    "lib/kv-router",
    "lib/router-plugins/catalog",
    "lib/router-plugins/builtin",
    "examples/router/custom-policy-example/soft-pin-repin",
    "examples/router/custom-policy-example/simple-filter-score-pick",
    "examples/router/custom-policy-example/catalog",
    "examples/router/custom-policy-example/disagg-filter-score-pick",
    "examples/router/custom-policy-example/epp",
    "examples/router/custom-policy-example/simple-stacked-score-pick",
    "lib/memory",
    "lib/kvbm-common",
    "lib/kvbm-config",
    "lib/kvbm-engine",
    "lib/kvbm-kernels",
    "lib/kvbm-consolidator",
    "lib/kvbm-logical",
    "lib/kvbm-physical",
    "lib/bench",
    "lib/backend-common",
    "lib/backend-common/examples/mocker",
    "lib/sidecar/common",
    "lib/sidecar/vllm",
    "lib/mocker/servers/vllm",
    "lib/sidecar/sglang",
    "lib/mocker/servers/sglang",
    "lib/sidecar/trtllm",
    "lib/bindings/c",
    "lib/bindings/python/codegen",
    "deploy/inference-gateway/ext-proc",
    "deploy/inference-gateway/sidecar",
]
resolver = "3"

[workspace.package]
version = "1.5.0"
edition = "2024"
description = "Dynamo Inference Framework"
authors = ["NVIDIA Inc. <sw-dl-dynamo@nvidia.com>"]
license = "Apache-2.0"
homepage = "https://github.com/ai-dynamo/dynamo"
repository = "https://github.com/ai-dynamo/dynamo.git"
keywords = ["llm", "genai", "inference", "nvidia", "distributed"]

[workspace.dependencies]
# Published separately by https://github.com/ai-dynamo/aisimulate.
aisimulate-core = { version = "=0.1.0-dev.2" }

# Local crates
dynamo-runtime = { path = "lib/runtime", version = "1.5.0" }
dynamo-llm = { path = "lib/llm", version = "1.5.0" }
dynamo-rl = { path = "lib/rl", version = "1.5.0" }
dynamo-tokenizers = { version = "=1.8.1" }
dynamo-renderer = { version = "=5.1.2" }
dynamo-tokens = { path = "lib/tokens", version = "1.5.0" }
dynamo-truthy = { path = "lib/truthy", version = "1.5.0" }
dynamo-data-gen = { path = "lib/data-gen", version = "1.5.0" }
dynamo-kv-hashing = { path = "lib/kv-hashing", version = "1.5.0" }
dynamo-memory = { path = "lib/memory", version = "1.5.0" }
dynamo-mocker = { path = "lib/mocker", version = "1.5.0" }
dynamo-kv-router = { path = "lib/kv-router", version = "1.5.0" }
dynamo-protocols = { version = "=5.4.1" }
dynamo-parsers = { version = "8.1.0" }

# Published on crates.io. To see all available versions:
#   web:          https://crates.io/crates/dynamo-parsers-v2/versions
#   sparse index: curl https://index.crates.io/dy/na/dynamo-parsers-v2   (one JSON line per release; read the "vers" field)
dynamo-parsers-v2 = { version = "0.3.2" }
dynamo-backend-common = { path = "lib/backend-common", version = "1.5.0" }
dynamo-sidecar-common = { path = "lib/sidecar/common", version = "1.5.0" }
fastokens = { version = "0.2.0" }


# kvbm
kvbm-common = { path = "lib/kvbm-common", version = "1.5.0" }
kvbm-config = { path = "lib/kvbm-config", version = "1.5.0" }
kvbm-consolidator = { path = "lib/kvbm-consolidator", version = "1.5.0" }
kvbm-engine = { path = "lib/kvbm-engine", version = "1.5.0" }
kvbm-kernels = { path = "lib/kvbm-kernels", version = "1.5.0" }
kvbm-logical = { path = "lib/kvbm-logical", version = "1.5.0" }
kvbm-physical = { path = "lib/kvbm-physical", version = "1.5.0" }

# velo
velo = { version = "0.12.0" }

# External dependencies
anyhow = { version = "1" }
lru = { version = "0.16" }
async-nats = { version = "0.49.1", features = ["service"] }
async-stream = { version = "0.3" }
async-trait = { version = "0.1" }
blake3 = { version = "1.8.7" }
bytes = { version = "1.9" }
chrono = { version = "0.4", default-features = false, features = [
    "alloc",
    "std",
    "clock",
    "now",
    "serde",
] }
cudarc = { version = "=0.19.8", features = ["cuda-version-from-build-system", "fallback-latest"] }
dashmap = { version = "6.1" }
moka = { version = "0.12", features = ["future"] }
derive_builder = { version = "0.20" }
derive-getters = { version = "0.5" }
either = { version = "1.13", features = ["serde"] }
etcd-client = { version = "0.17.0", features = ["tls"] }
futures = { version = "0.3" }
futures-util = { version = "0.3.32" }
fs4 = { version = "0.13.1" }
hf-hub = { version = "0.4.2", default-features = false }

# ModelExpress for model downloading
modelexpress-client = { version = "0.5.0" }
modelexpress-common = { version = "0.5.0" }

humantime = { version = "2.2.0" }
indexmap = { version = "2" }
ipnet = { version = "2" }
libc = { version = "0.2" }
oneshot = { version = "0.1.13", features = ["std", "async"] }
ordered-float = "4"
parking_lot = "0.12.5"
prometheus = { version = "0.14"}
rand = { version = "0.9.2" }
reqwest = { version = "0.12.24", default-features = false, featur

{
  "name": "html5-boilerplate",
  "version": "9.0.1",
  "description": "A professional front-end template for building fast, robust, and adaptable web apps or sites.",
  "keywords": [
    "h5bp",
    "template",
    "front-end"
  ],
  "homepage": "https://html5boilerplate.com/",
  "bugs": {
    "url": "https://github.com/h5bp/html5-boilerplate/issues"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/h5bp/html5-boilerplate.git"
  },
  "license": "MIT",
  "files": [
    "CHANGELOG.md",
    "LICENSE.txt",
    "package.json",
    "dist/",
    "README.md"
  ],
  "scripts": {
    "build": "gulp build",
    "prettier": "prettier --write ./**/*.{js,json,md,mjs,yml}",
    "test": "gulp archive && mocha --reporter spec --timeout 5000",
    "lint": "eslint ."
  },
  "devDependencies": {
    "@eslint/js": "^10.0.1",
    "archiver": "^7.0.1",
    "del": "^8.0.1",
    "eslint": "^10.6.0",
    "eslint-plugin-mocha": "^11.3.0",
    "glob": "^13.0.6",
    "globals": "^17.7.0",
    "gulp": "^5.0.1",
    "gulp-autoprefixer": "^10.0.0",
    "gulp-eslint-new": "^2.6.2",
    "gulp-header": "^2.0.12",
    "gulp-rename": "^2.1.0",
    "main.css": "3.0.0",
    "mocha": "^11.7.6",
    "prettier": "3.8.4"
  },
  "overrides": {
    "diff": "^8.0.3",
    "serialize-javascript": "^7.0.5"
  },
  "engines": {
    "node": ">=22"
  },
  "volta": {
    "node": "22.23.1"
  },
  "h5bp-configs": {
    "directories": {
      "archive": "archive",
      "dist": "dist",
      "src": "src",
      "test": "test"
    }
  }
}

{
  "name": "atlassian-mcp-server-package",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test scripts/*.test.mjs scripts/validation/*.test.mjs",
    "validate": "node scripts/validate-template.mjs"
  },
  "devDependencies": {
    "yaml": "2.9.0"
  }
}
